SELECT
,
 AS target_name
FROM ifj_schedule

    
        target_type = #{targetType}
    
    
        AND target_id = #{targetId}
    
    
        AND  LIKE #{targetNamePattern} ESCAPE '!'
    
    
        AND schedule_type = #{scheduleType}
    
    
        AND enabled = #{enabled}
    

ORDER BY update_time DESC, id DESC

SELECT

FROM ifj_schedule
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
ORDER BY id
